CREATE SCHEMA IF NOT EXISTS bronze;
CREATE TABLE IF NOT EXISTS bronze.nuxeo_posicoes_detalhadas (
    id BIGSERIAL PRIMARY KEY,
    placa VARCHAR(20)
);

SELECT DISTINCT UPPER(TRIM(placa)) AS placa FROM bronze.nuxeo_posicoes_detalhadas WHERE placa IS NOT NULL AND placa <> '';

