const response = $('02 - Buscar Frota Nuxeo API').first().json;
const token = $('01 - Nuxeo Auth').first().json.token;
const listaNuxeo = response.positions || response.targets || response || [];

const jaProcessadasItems = $input.all();
const jaProcessadasSet = new Set();
for (const item of jaProcessadasItems) {
  if (item.json && item.json.placa) {
    jaProcessadasSet.add(String(item.json.placa).trim().toUpperCase());
  }
}

const pendentes = [];
const placasVistas = new Set();

for (const v of listaNuxeo) {
  const placa = (v.identifier || '').trim().toUpperCase();
  if (!placa || placasVistas.has(placa)) continue;
  placasVistas.add(placa);

  if (jaProcessadasSet.has(placa)) {
    console.log(`[SKIP] Posições da Placa ${placa} já foram salvas.`);
    continue;
  }

  pendentes.push({
    json: {
      token,
      placa
    }
  });
}

console.log(`[BACKFILL POSICOES RESUMABLE] Total Nuxeo: ${listaNuxeo.length} | Já no Banco: ${jaProcessadasSet.size} | Pendentes: ${pendentes.length}`);
return pendentes;

const item = $input.first().json;
const token = item.token;
const placa = item.placa;

if (!placa) {
  return [{ json: { _skip: true } }];
}

const janelas = [
  { begin: '01/01/2026 00:00:00', end: '31/01/2026 23:59:59' },
  { begin: '01/02/2026 00:00:00', end: '28/02/2026 23:59:59' },
  { begin: '01/03/2026 00:00:00', end: '31/03/2026 23:59:59' },
  { begin: '01/04/2026 00:00:00', end: '30/04/2026 23:59:59' },
  { begin: '01/05/2026 00:00:00', end: '31/05/2026 23:59:59' },
  { begin: '01/06/2026 00:00:00', end: '30/06/2026 23:59:59' },
  { begin: '01/07/2026 00:00:00', end: '31/07/2026 23:59:59' }
];

const requests = [];
for (const j of janelas) {
  const beginEnc = encodeURIComponent(j.begin);
  const endEnc = encodeURIComponent(j.end);
  requests.push({
    json: {
      token,
      placa,
      begin: j.begin,
      end: j.end,
      url: `https://api.nuxeo.com.br/rest/report/positionByPlate/?plate=${placa}&begin=${beginEnc}&end=${endEnc}&count=1000`
    }
  });
}

console.log(`[BACKFILL POSICOES RESUMABLE] Processando Placa Pendente: ${placa}`);
return requests;

const rawItems = $input.all();

const esc = (v) => v != null ? String(v).replace(/'/g, "''") : null;
const valStr = (v) => v != null ? `'${esc(v)}'` : 'NULL';
const valNum = (v) => (v != null && !isNaN(v)) ? Number(v) : 'NULL';
const valBool = (v) => typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : 'NULL';
const valJson = (obj) => `'${JSON.stringify(obj).replace(/'/g, "''")}'::jsonb`;

const sqlStatements = [];
sqlStatements.push(`
CREATE SCHEMA IF NOT EXISTS bronze;
CREATE TABLE IF NOT EXISTS bronze.nuxeo_posicoes_detalhadas (
    id BIGSERIAL PRIMARY KEY,
    nuxeo_pos_id BIGINT,
    placa VARCHAR(20),
    serial VARCHAR(50),
    altitude NUMERIC(8,2),
    endereco TEXT,
    cidade VARCHAR(150),
    estado VARCHAR(50),
    pais VARCHAR(50),
    latitude NUMERIC(10,6),
    longitude NUMERIC(10,6),
    data_gps TEXT,
    data_server TEXT,
    ignicao BOOLEAN,
    bateria TEXT,
    alerta_bateria BOOLEAN,
    bloqueio BOOLEAN,
    panico BOOLEAN,
    odometro BIGINT,
    velocidade NUMERIC(6,2),
    motorista TEXT,
    cliente INT,
    tipo_cliente INT,
    payload_json JSONB,
    ingested_at TIMESTAMPTZ DEFAULT NOW()
);
`);

let totalRecords = 0;
const allPositions = [];

for (const item of rawItems) {
  const resp = item.json;
  if (resp._skip) continue;
  const positions = resp.positions || [];
  if (!Array.isArray(positions) || positions.length === 0) continue;
  for (const pos of positions) {
    allPositions.push({
      ...pos,
      placaFallback: resp.placa
    });
  }
}

if (allPositions.length === 0) {
  return [{ json: { _sql: "SELECT 0 AS inseridos;", totalRecords: 0 } }];
}

const chunkSize = 500;
for (let i = 0; i < allPositions.length; i += chunkSize) {
  const chunk = allPositions.slice(i, i + chunkSize);
  const values = chunk.map(pos => {
    totalRecords++;
    const placaFinal = pos.identifier || pos.placaFallback;
    return '('
      + valNum(pos.id) + ', '
      + valStr(placaFinal) + ', '
      + valStr(pos.serial) + ', '
      + valNum(pos.altitude) + ', '
      + valStr(pos.address) + ', '
      + valStr(pos.city) + ', '
      + valStr(pos.state) + ', '
      + valStr(pos.country) + ', '
      + valNum(pos.latitude) + ', '
      + valNum(pos.longitude) + ', '
      + valStr(pos.dateGps) + ', '
      + valStr(pos.dateServerWriter) + ', '
      + valBool(pos.ignition) + ', '
      + valStr(pos.battery) + ', '
      + valBool(pos.batteryAlert) + ', '
      + valBool(pos.block) + ', '
      + valBool(pos.panic) + ', '
      + valNum(pos.odometer) + ', '
      + valNum(pos.speed) + ', '
      + valStr(pos.driver) + ', '
      + valNum(pos.costumer) + ', '
      + valNum(pos.costumerType) + ', '
      + valJson(pos)
      + ')';
  }).join(',\n');

  sqlStatements.push(`
    INSERT INTO bronze.nuxeo_posicoes_detalhadas (
      nuxeo_pos_id, placa, serial, altitude, endereco, cidade, estado, pais,
      latitude, longitude, data_gps, data_server, ignicao, bateria, alerta_bateria,
      bloqueio, panico, odometro, velocidade, motorista, cliente, tipo_cliente, payload_json
    ) VALUES ${values};
  `);
}

return [{ json: { _sql: sqlStatements.join('\n'), totalRecords } }];
